function kahnTopoSort(graph):
  # graph: dict node -> list of neighbors (prerequisites)
  indegree = {u: 0 for u in graph}
  for u in graph:
    for v in graph[u]:
      indegree[v] += 1
  queue = []
  for u in graph:
    if indegree[u] == 0:
      queue.append(u)
  order = []
  while queue:
    u = queue.pop(0)   # BFS queue
    order.append(u)
    for v in graph[u]:
      indegree[v] -= 1
      if indegree[v] == 0:
        queue.append(v)
  if len(order) != len(graph):
    return []   # cycle exists
  return order

